// Только просмотр чатов new02: пустой чат с «QA П5 0014» (мэтч 7.11, сообщений нет) и чат с «QA П3 0012» (ответ на сторис 7.11).
// @data — только из-за одноразового refresh-токена new02 (те же сессии в других @data-тестах), данные не меняет.
import { test, expect } from '../../fixtures';
import { saveSession } from '../_shared/session';
import { N3, phone, openChat } from './chat-personal-helpers';

const N5 = 'QA П5 0014';

test.describe('Личный чат — просмотр (new02)', () => {
  test.describe.configure({ timeout: 120_000 });

  test('Пустой чат: шапка, карточка «שם, גיל», «לפרופיל של…», чипы ים/מוזיקה חיה/קפה, placeholder справа @iphone @data (#d6881a)', async ({ asUser }) => {
    const p = await asUser('new02');
    try {
      await phone(p);
      await openChat(p, N5);
      // Шапка 867-2533: «חזרה», имя, «⋯», аватар → профиль (Р1, Р4).
      await expect(p.getByRole('button', { name: 'חזרה' })).toBeVisible();
      await expect(p.getByRole('button', { name: N5, exact: true })).toBeVisible();
      await expect(p.getByRole('button', { name: "פעולות על הצ'אט" })).toBeVisible();
      await expect(p.getByRole('button', { name: `לפרופיל של ${N5}` })).toBeVisible();
      // Пустой чат 943-15426: карточка «שם, גיל», дата мэтча, ссылка на профиль, подсказка с чипами (Р1, Р4).
      const intro = p.getByTestId('chat-intro');
      await expect(intro.getByText(new RegExp(`^${N5}, \\d+$`))).toBeVisible();
      await expect(intro.getByText(/^התאמתם /)).toBeVisible();
      await expect(p.getByRole('link', { name: new RegExp(`^לפרופיל של ${N5}`) })).toBeVisible();
      await expect(p.getByText('איך לפתוח שיחה?')).toBeVisible();
      // Порядок чипов справа налево: ים → מוזיקה חיה → קפה (Р2).
      const x = async (name: string) => (await p.getByRole('button', { name, exact: true }).boundingBox())!.x;
      const [yam, music, coffee] = [await x('ים'), await x('מוזיקה חיה'), await x('קפה')];
      expect(yam, 'ים правее מוזיקה חיה').toBeGreaterThan(music);
      expect(music, 'מוזיקה חיה правее קפה').toBeGreaterThan(coffee);
      // Поле ввода: placeholder «כתוב הודעה» прижат вправо; «שליחה» неактивна при пустом поле (Р2, AC 3).
      const box = p.getByRole('textbox', { name: 'כתוב הודעה' });
      expect(await box.evaluate((e) => getComputedStyle(e).textAlign)).toMatch(/right|start/);
      await expect(p.getByRole('button', { name: 'שליחה' })).toBeDisabled();
      // Имя с латиницей в шапке в верном порядке: «QA» левее «0014» (Р4).
      const order = await p.getByRole('button', { name: N5, exact: true }).evaluate((el) => {
        const w = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
        let t: Text | null = null;
        while (w.nextNode()) if ((w.currentNode as Text).data.includes('QA')) { t = w.currentNode as Text; break; }
        if (!t) return null;
        const r = document.createRange();
        const left = (s: string) => { r.setStart(t!, t!.data.indexOf(s)); r.setEnd(t!, t!.data.indexOf(s) + s.length); return r.getBoundingClientRect().left; };
        return { qa: left('QA'), num: left('0014') };
      });
      expect(order, 'текст имени в шапке').not.toBeNull();
      expect(order!.qa, '«QA» стоит левее «0014»').toBeLessThan(order!.num);
    } finally {
      await saveSession(p, 'new02');
    }
  });

  test('Ответ на сторис: подпись «הגיב/ה לסטורי שלך», превью сторис 64×114, текст ответа @iphone @data (#d6881a)', async ({ asUser }) => {
    const p = await asUser('new02');
    try {
      await phone(p);
      await openChat(p, N3);
      // Карточка 867-2581: «<имя> הגיב/ה לסטורי שלך», превью сторис 64×114 (Р6, Р1, AC 6).
      await expect(p.getByText(`${N3} הגיב/ה לסטורי שלך`)).toBeVisible();
      const thumb = p.getByTestId('story-thumb');
      await expect(thumb).toBeVisible();
      const card = await thumb.evaluate((el) => {
        const all = [el, ...el.querySelectorAll('*')].map((n) => n.getBoundingClientRect());
        return all.some((r) => Math.abs(r.width - 64) <= 1 && Math.abs(r.height - 114) <= 1);
      });
      expect(card, 'внутри story-thumb есть карточка 64×114').toBeTruthy();
      await expect(p.getByTestId('bubble-peer').filter({ hasText: 'QA-AUTO r6 reply' })).toBeVisible();
      // Чат открыт на последнем сообщении (Р1).
      await expect(p.getByTestId(/^bubble-(mine|peer)$/).last()).toBeInViewport();
    } finally {
      await saveSession(p, 'new02');
    }
  });
});
